import { revalidateTag, unstable_cacheTag as cacheTag } from "next/cache";

import { getAllProducts } from "../lib/db.js";

async function ProductsList() {
  "use cache";

  cacheTag("products");
  const products = await getAllProducts();
  const cachedAt = new Date().toISOString();

  return (
    <section>
      <p>Cached at: {cachedAt}</p>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </section>
  );
}

export default function Page() {
  return (
    <main>
      <h1>Products</h1>
      <p>
        The list below is cached with the "products" tag. Submit the form to
        invalidate the cache and refresh the data.
      </p>
      <form
        action={async () => {
          "use server";
          revalidateTag("products");
        }}
      >
        <button type="submit">Invalidate products cache</button>
      </form>
      <ProductsList />
    </main>
  );
}
